   def separate_groups(s: str) -> List[str]:
       if not s:
           return []
       if s[0] == '(' and s[-1] == ')':
           return [s]
       result = []
       balance = 0
       start = 0
       for i, char in enumerate(s):
           if char == '(':
               balance += 1
           elif char == ')':
               balance -= 1
           if balance == 0:
               result.append(s[start:i+1])
               break
       for i in range(len(s) - 1, -1, -1):
           if s[i] == ')':
               balance += 1
           elif s[i] == '(':
               balance -= 1
           if balance == 0:
               result.append(s[i:len(s)])
               break
       for group in result:
           result.remove(group)
           rest = s.replace(group, "")
           sub_result = separate_groups(rest)
           if sub_result:
               result.extend(sub_result)
               break
       return result

